import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const b=JSON.parse('{"title":"Interface: ModuleMetadata","description":"","frontmatter":{},"headers":[],"relativePath":"api/twine/interfaces/ModuleMetadata.md","filePath":"api/twine/interfaces/ModuleMetadata.md"}'),i={name:"api/twine/interfaces/ModuleMetadata.md"};function c(n,e,d,l,s,f){return a(),o("div",null,[...e[0]||(e[0]=[r('<p><a href="./../">twine</a> / ModuleMetadata</p><h1 id="interface-modulemetadata" tabindex="-1">Interface: ModuleMetadata <a class="header-anchor" href="#interface-modulemetadata" aria-label="Permalink to &quot;Interface: ModuleMetadata&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/twine/src/core/module.interface.ts#L88" target="_blank" rel="noreferrer">core/module.interface.ts:88</a></p><p>Metadata attached to a class by the <a href="./../functions/Module.html">Module</a> decorator.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="activebydefault" tabindex="-1">activeByDefault? <a class="header-anchor" href="#activebydefault" aria-label="Permalink to &quot;activeByDefault?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>activeByDefault?</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/twine/src/core/module.interface.ts#L110" target="_blank" rel="noreferrer">core/module.interface.ts:110</a></p><p>Initial flag value, set on load. Default <code>false</code>.</p><hr><h3 id="area" tabindex="-1">area? <a class="header-anchor" href="#area" aria-label="Permalink to &quot;area?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>area?</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/twine/src/core/module.interface.ts#L107" target="_blank" rel="noreferrer">core/module.interface.ts:107</a></p><p>Makes this module an area: its tick and whole import subtree only run while its <code>active</code> flag is <code>1</code>.</p><p>A dormant area costs one check per tick. Flip it with <code>&lt;name&gt;/activate</code> / <code>&lt;name&gt;/deactivate</code> or a <a href="#trigger">trigger</a>.</p><hr><h3 id="dimension" tabindex="-1">dimension? <a class="header-anchor" href="#dimension" aria-label="Permalink to &quot;dimension?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>dimension?</strong>: <code>IdValue</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/twine/src/core/module.interface.ts#L123" target="_blank" rel="noreferrer">core/module.interface.ts:123</a></p><p>The dimension this area lives in. Its lifecycle, ticks and triggers all run in it.</p><p>Saves adding <code>.in(...)</code> to every handler, where one missed call silently checks the wrong dimension. Child areas inherit it.</p><hr><h3 id="env" tabindex="-1">env? <a class="header-anchor" href="#env" aria-label="Permalink to &quot;env?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>env?</strong>: <a href="./../type-aliases/BuildEnv.html"><code>BuildEnv</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/twine/src/core/module.interface.ts#L126" target="_blank" rel="noreferrer">core/module.interface.ts:126</a></p><p>Build environments this module is included in, e.g. <code>[&quot;dev&quot;]</code>. Omit for all.</p><hr><h3 id="imports" tabindex="-1">imports? <a class="header-anchor" href="#imports" aria-label="Permalink to &quot;imports?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>imports?</strong>: <a href="./../type-aliases/ModuleRef.html"><code>ModuleRef</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/twine/src/core/module.interface.ts#L98" target="_blank" rel="noreferrer">core/module.interface.ts:98</a></p><p>Child modules to include. Removing one leaves it out of the build.</p><p>Deduplicated by identity: a shared class is built once, but two <code>Door(...)</code> calls are two doors.</p><hr><h3 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to &quot;name&quot;">​</a></h3><blockquote><p><strong>name</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/twine/src/core/module.interface.ts#L90" target="_blank" rel="noreferrer">core/module.interface.ts:90</a></p><p>Stable module id. Used as the scoreboard name and the namespace for its functions.</p><hr><h3 id="tickevery" tabindex="-1">tickEvery? <a class="header-anchor" href="#tickevery" aria-label="Permalink to &quot;tickEvery?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>tickEvery?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/twine/src/core/module.interface.ts#L132" target="_blank" rel="noreferrer">core/module.interface.ts:132</a></p><p>Runs this module&#39;s <code>onTick</code> every <code>tickEvery</code> ticks instead of every tick. Still inside area gating.</p><hr><h3 id="tickphase" tabindex="-1">tickPhase? <a class="header-anchor" href="#tickphase" aria-label="Permalink to &quot;tickPhase?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>tickPhase?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/twine/src/core/module.interface.ts#L138" target="_blank" rel="noreferrer">core/module.interface.ts:138</a></p><p>Tick offset (<code>0..tickEvery-1</code>) for the throttled <code>onTick</code>. Omit to have modules sharing a <code>tickEvery</code> spread across ticks automatically.</p><hr><h3 id="trigger" tabindex="-1">trigger? <a class="header-anchor" href="#trigger" aria-label="Permalink to &quot;trigger?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>trigger?</strong>: <a href="./../type-aliases/AreaTrigger.html"><code>AreaTrigger</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/382eb586bbc0ef887dc1c01514f7f70e2ff83db5/twine/src/core/module.interface.ts#L115" target="_blank" rel="noreferrer">core/module.interface.ts:115</a></p><p>How this area switches itself on (see <a href="./../type-aliases/AreaTrigger.html">AreaTrigger</a>). Omit to activate manually.</p>',52)])])}const p=t(i,[["render",c]]);export{b as __pageData,p as default};
